INSERT INTO activities (id,date,description,person) VALUES (222,'2026-07-27','Reopened the ticket on zoho desk related to application crash when navigating to opening stock which was marked as closed, evaluated the issue in the newly released version 2.9 of Linkedcare mobile application and found that it is still not solved so reopened the ticket.','Sayan');
