INSERT INTO activities (id,date,description,person) VALUES (227,'2026-07-28','Identified and raised a production ticket for the Linkedcare Mobile Application (Android & iOS) where, after successfully submitting a Counter Sale, the application does not redirect the user to the Sales Dashboard. Additionally, observed that the application remains on the New Counter Sale page with only the Customer Name and Mobile Number fields retained while the remaining fields are cleared, resulting in an inconsistent user experience.','Sayan');
