INSERT INTO activities (id,date,description,person) VALUES (231,'2026-07-29','Added pathology tests in the LIAMP backend using the test list shared by Dharmik Sir. Additionally, added the missing details for each test, including Subtest (where applicable), Reference Range (Low & High Values), Unit, and Result Type.','Sayan');
INSERT INTO activities (id,date,description,person) VALUES (232,'2026-07-30','Identified and raised a production ticket regarding an issue in the OPD Sale workflow across the Linkedcare Web and Mobile Applications (Android & iOS). Observed that after retrieving a patient''s prescription, the Duration and Prescribed Quantity displayed in the medicine summary are incorrect. On the website, these values are corrected only after clicking Proceed, whereas in the mobile application the Prescribed Quantity is not displayed even after proceeding, resulting in inconsistent and incorrect prescription details.','Sayan');
INSERT INTO activities (id,date,description,person) VALUES (233,'2026-07-30','Identified and raised a production ticket for the Linkedcare Mobile Application v2.9.0 (Android & iOS) where OPD Sales cannot be completed. Although prescribed medicines are retrieved successfully, clicking Submit does not create the sale. Instead, the application redirects the user back to the Sales Dashboard without displaying any confirmation or error message, while the same workflow functions correctly on the website.','Sayan');
INSERT INTO activities (id,date,description,person) VALUES (234,'2026-07-30','Connected with Mr. Parth from Veera Orthopaedic Hospital regarding queries related to ABHA Integration and software linkage. Clarified his doubts, and addressed all of his queries.','Sayan');
INSERT INTO activities (id,date,description,person) VALUES (235,'2026-07-31','Connected with Mr. Mohd Ashique from Charitable & Multispeciality Hospital, guided him about the interim bill of admitted patient, billing dashboard in new billing module and patient summary in the doctor. Also he has query about billing header footer, shared that query with Varun Sir also. Also their pharmacy setup was not completed so guided him about filling the opening stock file for further process','Sayan');
