INSERT INTO activities (id,date,description,person) VALUES (257,'2026-08-12','Connected with Mr. Vipul from Kalarav Hospital, Amreli, and completed the software linkage and backend setup, including SKU addition, enabling the required modules and settings, and ABHA integration. Subsequently connected with him on AnyDesk for the frontend setup and configured wards, beds, shifts, and doctor details, while also guiding him on adding staff. During the setup, Mr. Vipul mentioned that Sunita Ma’am had informed him that someone from the team would visit the hospital for setup and training, so he requested an onsite hospital visit. Provided him demo of the Doctor, Assistant, and Billing Head dashboards along with their respective workflows.','Sayan');
