INSERT INTO activities (id,date,description,person) VALUES (259,'2026-08-13','Connected with Ms. Kashish Singh from Shiv Shakti Hospital and shared the quotation for their subscription renewal.','Sayan');
INSERT INTO activities (id,date,description,person) VALUES (260,'2026-08-13','Updated the Subject and Quote Stage fields in Zoho CRM for onboarded customers.','Sayan');
INSERT INTO activities (id,date,description,person) VALUES (261,'2026-08-13','Re-evaluated recently closed tickets on the newly released LinkedCare Mobile Application v2.9.1 for iOS to verify whether the reported issues had been resolved. During testing, found that the issue related to the application becoming unresponsive while navigating from the Sales dropdown to the Purchase section on iOS 26.5.2 was still unresolved despite being marked as closed. Reopened the ticket with the latest observations for further investigation.','Sayan');
INSERT INTO activities (id,date,description,person) VALUES (262,'2026-08-13','Connected with Dr. Jaydip from Kalarav Children Hospital and shared the Certificate of Compliance for their hospital.','Sayan');
INSERT INTO activities (id,date,description,person) VALUES (263,'2026-08-14','Connected with Mr. Ashique from Charitable Hospital to check the status of the opening stock file required for their pharmacy setup. He informed that it is still in process. Also discussed the subscription renewal, and he confirmed that they would like to continue for the same 6-month duration with 15 beds, 4 doctors, and 7 staff members.','Sayan');
INSERT INTO activities (id,date,description,person) VALUES (264,'2026-08-14','Raised a ticket for an issue in LinkedCare iOS Mobile Application v2.9.1 where the *Purchase Return List always displays the returned quantity as 1, regardless of the actual quantity entered and processed during the purchase return','Sayan');
INSERT INTO activities (id,date,description,person) VALUES (265,'2026-08-14','Connected with Ms. Kashish from Shiv Shakti Hospital to follow up regarding the renewal quotation. She confirmed that she has received it but has not reviewed it yet and will review it once she gets free.','Sayan');
INSERT INTO activities (id,date,description,person) VALUES (266,'2026-08-17','Shared the renewal quotation with Dr. Mohd Ashique from Charitable Hospital and tried connecting with him multiple times regarding the renewal, but there was no response from his side.','Sayan');
INSERT INTO activities (id,date,description,person) VALUES (267,'2026-08-17','Tried connecting with Mr. Kundan Kumar from Doctors For You Hospital regarding the subscription renewal. He did not answer the calls or respond to the WhatsApp message.','Sayan');
INSERT INTO activities (id,date,description,person) VALUES (268,'2026-08-17','Connected with Ms. Kashish Singh from Shiv Shakti Hospital regarding the renewal status. She informed that she will complete the renewal payment within the next 2 days.','Sayan');
INSERT INTO activities (id,date,description,person) VALUES (269,'2026-08-17','Raised a ticket for an issue in Backend LIAMP where Shree Siddhivinayak Hospital does not appear when searched by hospital name, although the same hospital is correctly displayed when searched using its registered mobile number.','Sayan');
INSERT INTO activities (id,date,description,person) VALUES (270,'2026-08-18','Connected with Dr. Mohd Ashique from Charitable Hospital regarding the renewal quotation. Received the payment confirmation and updated the hospital SKU accordingly. After the SKU update, identified an issue where the updated subscription end date was not reflected for the doctors associated with the hospital. Informed Varun Sir and raised a ticket for the issue. The issue has now been resolved, and the updated subscription end date is correctly reflected for the doctor logins as well.','Sayan');
INSERT INTO activities (id,date,description,person) VALUES (271,'2026-08-18','Connected with Mr. Kundan Kumar from Doctors For You regarding the renewal quotation and identified an incorrect subscription end date in LIAMP. Their subscription had been extended by 2 months and should now end on 30th September, whereas LIAMP was showing 31st August. Discussed the discrepancy with Varun Sir and got the subscription end date corrected.','Sayan');
INSERT INTO activities (id,date,description,person) VALUES (272,'2026-08-18','Configured the prescription template for Shree Sidhivinayak Hospital using the template shared by Dharmik Sir, as there was an issue with the incorrect positioning/misprinting of fields on the prescription.','Sayan');
