INSERT INTO discussions (id,hospital_id,date,summary) VALUES (6,24,'2026-07-30','Connected with Mr. Parth from Veera Orthopaedic Hospital regarding queries related to ABHA Integration and software linkage. Clarified his doubts, and addressed all of his queries.');
