INSERT INTO discussions (id,hospital_id,date,summary) VALUES (10,5,'2026-07-21','Connected with Kundan Kumar (doctors for you), guided him about all the queries he asked via connecting with him on google meet.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (11,39,'2026-07-20','Informed about new updates. He is out of station and asked to call 2 days later for walkthrough of new featues');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (12,39,'2026-07-27','Connected wtih Mr. Nitin Ladumor, He was facing issue in logging in as he mistakenly deleted the doctor, connected with him on anydesk, added the doctor again, assisted him in doing the first time login for doctor as well as assistant. Guided the full workflow of OPD by creating new patient, setting appointment from assistant dashboard, starting consulation from the doctor''s dashboard, consultation page and finalizing prescription.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (13,39,'2026-07-28','Added the header & footer of their hospital in the prescription template');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (14,31,'2026-08-04','Connected with Mr. Khagendra Dadsena from Sai Care Multispeciality Hospital regarding software linkage. He informed that they were occupied with patient consultations and requested to reconnect tomorrow morning to continue the process.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (15,31,'2026-08-05','Connected with Mr. Khagendra Dadsena and Dr. Nabin Tandi from Sai Care Multispeciality Hospital, completed the software linkage using the Bridge ID on NHPR and shared the zoho onboarding form for further process. Also doctor had some doubt related to PMJAY so answered his queries related to that');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (16,31,'2026-08-06','Connected with Mr. Khagendra Dadsena, Ms. Roshani, and Mr. Neeraj Sahu from Sai Care Multispeciality Hospital to verify and confirm the doctors'' names and mobile numbers. Subsequently completed the backend setup in LIAMP by creating the hospital, adding the required SKU, configuring doctor profiles, creating beds, enabling the required modules, integrating ABHA, enabling GPE, and creating the required SOAP components for the doctors. Additionally, conducted Clinic Admin, Assistant, and Doctor training, covering the configuration of wards, ward rooms, bed types, beds, shifts, and staff, assisted with the first-time login for doctors and staff using the default password, and provided a complete walkthrough of the patient workflow, including patient registration, appointment creation, consultation, IPD admission, and patient discharge.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (17,31,'2026-08-07','Connected with Ms. Roshani from Sai Care Hospital and provided Billing Head and Nurse training. Also conducted a complete walkthrough of the OPD and IPD workflows, including patient creation from the Assistant Dashboard, doctor assignment, starting consultation from the Doctor Dashboard, using Disposition (Admit), entering the required details, finalizing and saving prescriptions, creating patient bills, and managing patients through the Nurse Module. Additionally, configured their prescription template as per the hospital''s requirements.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (18,31,'2026-08-10','Shared Certificate of Compliance');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (19,36,'2026-08-08','Completed the backend setup, added the doctor, integrated ABHA, and enabled the required modules. Separately connected with Dr. Jaydip for the frontend setup, including wards, ward rooms, beds, staff, shifts, and prescription template configuration. Assisted with first-time login and provided Assistant and Doctor dashboard training. Also guided him on filling the opening stock file for the pharmacy setup.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (20,36,'2026-08-11','Connected with Dr. Jaydip from Kalrav Hospital regarding the IPD workflow demonstration. He was occupied with OPD today and requested to take the demonstration tomorrow.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (21,34,'2026-08-12','Connected with Dr. Jaydip from Kalarav Children Hospital and provided a demonstration of the IPD workflow, including patient registration, consultation, patient admission, and discharge process.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (22,34,'2026-08-13','Connected with Dr. Jaydip from Kalarav Children Hospital and shared the Certificate of Compliance for their hospital.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (23,16,'2026-07-20','New license allocation for another doctor.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (24,2,'2026-07-20','Infromed about new updates in billing and ipd modules, For walkthrough she said she is busy today and asked to call tomorrow');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (25,2,'2026-07-21','Tried connecting to Shiv Shakti Hospital for walkthrough but no response from their side');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (26,2,'2026-07-23','Connected with Ms. Kashish from Shiv Shakti Hospital for a walkthrough of the newly introduced features in the Billing and IPD modules. Guided her through the Patient Summary feature, including the summary of the patient''s last five OPD visits, current IPD admission details, and previous IPD visits. Also demonstrated the Interim Bill feature in the Billing module. During the session, she encountered an issue while discharging a patient, so I assisted her in completing the discharge process and successfully finalizing the patient''s bill.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (27,2,'2026-07-24','Connected with Shiv Shakti Hospital as she was facing issue in creating new patient with ABHA, guided her to create new patient by updating the mobile number on ABHA. Also solved her query regarding creating bill directly from doctors dashboard.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (28,2,'2026-07-31','Connected with Ms Kashish from Shiv Shakti Hospital, she was having issue in discharging admitted patients, connected with her on anydesk and guided her in creating discharge summary, finalizing bill and discharging patients');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (29,2,'2026-08-05','Connected with Ms Kashish from Shiv Shakti Hospital as she was facing issue in creating appointment of ABHA patient due to mobile number was not updated, connected with her on anydesk and guided her steps by steps to update the mobile number Also there was issue in her account related to licensing, discussed the issue with Varun sir and resolved the issue.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (30,2,'2026-08-10','Connected with Ms. Kashish regarding the subscription renewal. She requested a quotation for the same 6-month duration as their current plan.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (31,2,'2026-08-13','Connected with Ms. Kashish Singh from Shiv Shakti Hospital and shared the quotation for their subscription renewal.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (32,2,'2026-08-14','Connected with Ms. Kashish from Shiv Shakti Hospital to follow up regarding the renewal quotation. She confirmed that she has received it but has not reviewed it yet and will review it once she gets free.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (33,1,'2026-07-20','Call to inform about new updates on software but no response');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (34,1,'2026-07-31','Connected with Mr. Mohd Ashique from Charitable & Multispeciality Hospital, guided him about the interim bill of admitted patient, billing dashboard in new billing module and patient summary in the doctor. Also he has query about billing header footer, shared that query with Varun Sir also. Also their pharmacy setup was not completed so guided him about filling the opening stock file for further process');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (35,1,'2026-08-03','Connected with Mr. Ashique regarding the pharmacy setup, he said he has not filled the opening stock file yet and will file it by end of the day and will send to us for further process');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (36,1,'2026-08-14','Connected with Mr. Ashique from Charitable Hospital to check the status of the opening stock file required for their pharmacy setup. He informed that it is still in process. Also discussed the subscription renewal, and he confirmed that they would like to continue for the same 6-month duration with 15 beds, 4 doctors, and 7 staff members.');
