INSERT INTO discussions (id,hospital_id,date,summary) VALUES (80,10,'2026-08-11','Followed up with Mr. Dharmendra for Shree Amruta Hospital frontend configuration. As requested by the hospital yesterday, I had shared the information over WhatsApp regarding the details they should keep ready before starting the frontend setup. He informed that the hospital is currently occupied with a celebration and will connect if they get time today. Therefore, the frontend configuration could not be initiated today.');
