INSERT INTO discussions (id,hospital_id,date,summary) VALUES (148,31,'2026-08-04','Connected with Mr. Khagendra Dadsena and Dr. Nabin Tandi from Sai Care Multispeciality Hospital, completed the software linkage using the Bridge ID on NHPR and shared the zoho onboarding form for further process. Also doctor had some doubt related to PMJAY so answered his queries related to that');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (149,2,'2026-08-04','Connected with Ms Kashish from Shiv Shakti Hospital as she was facing issue in creating appointment of ABHA patient due to mobile number was not updated, connected with her on anydesk and guided her steps by steps to update the mobile number Also there was issue in her account related to licensing, discussed the issue with Varun sir and resolved the issue.');
