INSERT INTO discussions (id,hospital_id,date,summary) VALUES (152,31,'2026-08-06','Connected with Ms. Roshani from Sai Care Hospital and provided Billing Head and Nurse training. Also conducted a complete walkthrough of the OPD and IPD workflows, including patient creation from the Assistant Dashboard, doctor assignment, starting consultation from the Doctor Dashboard, using Disposition (Admit), entering the required details, finalizing and saving prescriptions, creating patient bills, and managing patients through the Nurse Module. Additionally, configured their prescription template as per the hospital''s requirements.');
