INSERT INTO discussions (id,hospital_id,date,summary) VALUES (181,25,'2026-06-17','[Shree balaji multispecialty hospital] Admin Manoj has not been responding to calls or messages. After multiple follow-ups, he connected once for admin setup and training on 17-06-2026. Since then, he has neither connected again nor confirmed the pending doctor details required for further setup and training.');
