INSERT INTO discussions (id,hospital_id,date,summary) VALUES (183,17,'2026-06-15','[Om Maternity hospital and laproscopy centre] The hospital has not been operational for a long time. As per their shared timeline, regular follow-ups have been made after 15 June with both the doctor and admin. They informed that staff details need to be updated before training can begin.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (184,17,'2026-07-01','[Om Maternity hospital and laproscopy centre] Connected with OM Maternity Hospital admin, Gautam, and assisted him in updating staff members through the admin frontend. Also connected with the respective staff members to initiate their training');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (185,17,'2026-07-02','[Om Maternity hospital and laproscopy centre] Connected with the assistant of OM Maternity Hospital and assisted with first-time login, password creation, and provided training of the module.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (186,17,'2026-07-06','[Om Maternity hospital and laproscopy centre] Assisted Om Maternity Hospital with queries related to ABHA registration for newborn babies. Coordinated with Varun Sir to understand the available registration process and communicated the possible solutions and guidance to the hospital');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (187,17,'2026-07-07','[Om Maternity hospital and laproscopy centre] Connected with the pharmacist of OM Maternity Hospital and assisted him with the first-time login and password creation. Guided him through the process of opening stock using the Excel template and provided training on the Pharmacy module through the web version.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (188,17,'2026-07-09','[Om Maternity hospital and laproscopy centre] Connected with the Lab Technician of OM Maternity Hospital, assisted with the first-time login process, and provided training on the Lab module.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (189,17,'2026-07-10','[Om Maternity hospital and laproscopy centre] Connected with the Admin of OM Maternity Hospital Assisted him in completing remaining setup, informed him that training has been completed for all created users, advised them to start using the software for daily consultations, and also shared the Certificate of Compliance on their email ID.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (190,17,'2026-07-13','[Om Maternity hospital and laproscopy centre] Connected with the pharmacist of OM Maternity Hospital to follow up on the opening stock list status. They informed that they will complete it shortly and share the Excel file for further integration of the pharmacy stock.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (191,17,'2026-07-20','[Om Maternity hospital and laproscopy centre] connected with the doctor to tell him that new updates are realeased for our billing module he said currently the hospital staff is not using our software as it is newly operated hospital and they are not fimilar of using software so this is the reason they are not actively using software and not require billing modulke new updates walkthrough');
