INSERT INTO discussions (id,hospital_id,date,summary) VALUES (197,22,'2026-07-26','Connected wtih Mr. Nitin Ladumor, He was facing issue in logging in as he mistakenly deleted the doctor, connected with him on anydesk, added the doctor again, assisted him in doing the first time login for doctor as well as assistant. Guided the full workflow of OPD by creating new patient, setting appointment from assistant dashboard, starting consulation from the doctor''s dashboard, consultation page and finalizing prescription.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (198,22,'2026-07-28','Connected with Mr. Parth and Shared The Certificate of Compliance with Them. Also queried about no usage of software till now so he said they will start using it after 10-15 days.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (199,22,'2026-07-28','Connected with Mr. Apar Mahajan to know about when they will start using the software. He said they have applied for PMJAY and will start once they get the approval');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (200,22,'2026-07-29','Connected with Mr. Parth from Veera Orthopaedic Hospital regarding queries related to ABHA Integration and software linkage. Clarified his doubts, and addressed all of his queries.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (201,1,'2026-07-30','Connected with Mr. Mohd Ashique from Charitable & Multispeciality Hospital, guided him about the interim bill of admitted patient, billing dashboard in new billing module and patient summary in the doctor. Also he has query about billing header footer, shared that query with Varun Sir also. Also their pharmacy setup was not completed so guided him about filling the opening stock file for further process');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (202,22,'2026-08-02','Connected with Mr. Ashique regarding the pharmacy setup, he said he has not filled the opening stock file yet and will file it by end of the day and will send to us for further process');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (203,5,'2026-08-02','Continued working on the LinkedCare Help Center (CMS) by creating user guides for Ward Management (Wards, Ward Rooms, Bed Types & Beds), Adding Doctors & License Allocation, and Adding Rooms, including step-by-step instructions and key notes to assist administrators with the initial LinkedCare setup.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (204,22,'2026-08-03','Connected with Mr. Khagendra Dadsena from Sai Care Multispeciality Hospital regarding software linkage. He informed that they were occupied with patient consultations and requested to reconnect tomorrow morning to continue the process.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (205,22,'2026-08-04','Connected with Mr. Khagendra Dadsena and Dr. Nabin Tandi from Sai Care Multispeciality Hospital, completed the software linkage using the Bridge ID on NHPR and shared the zoho onboarding form for further process. Also doctor had some doubt related to PMJAY so answered his queries related to that');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (206,5,'2026-08-05','Connected with Mr. Khagendra Dadsena from Sai Care Multispeciality Hospital to verify and confirm the doctors'' names and mobile numbers. Subsequently completed the backend setup in LIAMP by creating the hospital, adding the required SKU, configuring doctor profiles, creating beds, enabling the required modules, integrating ABHA, enabling GPE, and creating the required SOAP components for the doctor.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (207,5,'2026-08-05','Connected with Ms. Roshani and Mr. Neeraj Sahu from Sai Care Multispeciality Hospital and conducted Clinic Admin, Assistant, and Doctor training. The training included configuration of wards, ward rooms, bed types, beds, shifts, and staff, assisted with the first-time login for doctors and staff using the default password, and a complete walkthrough of the patient workflow, including patient registration, appointment creation, consultation, IPD admission, and patient discharge.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (208,22,'2026-08-11','Connected with Mr. Vipul from Kalarav Hospital, Amreli, and completed the software linkage and backend setup, including SKU addition, enabling the required modules and settings, and ABHA integration. Subsequently connected with him on AnyDesk for the frontend setup and configured wards, beds, shifts, and doctor details, while also guiding him on adding staff. During the setup, Mr. Vipul mentioned that Sunita Ma’am had informed him that someone from the team would visit the hospital for setup and training, so he requested an onsite hospital visit. Provided him demo of the Doctor, Assistant, and Billing Head dashboards along with their respective workflows.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (209,1,'2026-08-13','Connected with Mr. Ashique from Charitable Hospital to check the status of the opening stock file required for their pharmacy setup. He informed that it is still in process. Also discussed the subscription renewal, and he confirmed that they would like to continue for the same 6-month duration with 15 beds, 4 doctors, and 7 staff members.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (210,22,'2026-08-10','[shree Amrutam hospital] bridge id provided to dharminder their pmjy partner he himself linked the software Completed the software linkage and backend configuration for Shree Amruta Hospital in LIAMP. Subsequently connected with Mr. Dharminder regarding the frontend setup, who shared the contact details of their executive, Mr. Kishan Babariya. Connected with Mr. Kishan and, as requested by the hospital, shared the details of the information they need to keep ready before starting the frontend configuration, including ward, bed, staff, shift, ADT, and OT-related configurations. The same message was shared with both contacts over WhatsApp for their reference.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (211,22,'2026-08-11','[shree Amrutam hospital] Followed up with Mr. Dharmendra for Shree Amruta Hospital frontend configuration. As requested by the hospital yesterday, I had shared the information over WhatsApp regarding the details they should keep ready before starting the frontend setup. He informed that the hospital is currently occupied with a celebration and will connect if they get time today. Therefore, the frontend configuration could not be initiated today.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (212,22,'2026-08-12','[shree Amrutam hospital] 2. Followed up with Mr. Dharmendra for Shree Amruta Hospital regarding the pending frontend configuration. He informed that his executive, Mr. Kishan Babariya, would connect for the setup. Mr. Kishan connected and rescheduled the frontend configuration session for tomorrow at 11:00 AM.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (213,22,'2026-08-13','[shree Amrutam hospital] Connected with Mr. Kishan Babariya regarding the pending frontend setup for Shree Amruta Hospital. He informed that they are still gathering the required hospital details and will connect once all the information is ready for the configuration.');
