INSERT INTO discussions (id,hospital_id,date,summary) VALUES (241,1,'2026-08-18','Connected with Dr. Mohd Ashique from Charitable Hospital regarding the renewal quotation. Received the payment confirmation and updated the hospital SKU accordingly. After the SKU update, identified an issue where the updated subscription end date was not reflected for the doctors associated with the hospital. Informed Varun Sir and raised a ticket for the issue. The issue has now been resolved, and the updated subscription end date is correctly reflected for the doctor logins as well.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (242,5,'2026-08-18','Connected with Mr. Kundan Kumar from Doctors For You regarding the renewal quotation and identified an incorrect subscription end date in LIAMP. Their subscription had been extended by 2 months and should now end on 30th September, whereas LIAMP was showing 31st August. Discussed the discrepancy with Varun Sir and got the subscription end date corrected.');
INSERT INTO discussions (id,hospital_id,date,summary) VALUES (243,19,'2026-08-18','Configured the prescription template for Shree Sidhivinayak Hospital using the template shared by Dharmik Sir, as there was an issue with the incorrect positioning/misprinting of fields on the prescription.');
